functions.testToBreakUp:
{
   var _loc5_;
   var _loc4_;
   var _loc3_;
   if(target.type == "头盔" || target.type == "衣服" || target.type == "武器" || target.type == "鞋")
   {
      _loc4_ = "";
      _loc5_ = target.grade;
      switch(_loc5_)
      {
         case 0:
            _parent._parent.createThing({type:"魔魂晶石"});
            _loc4_ = "获得 魔魂晶石";
            break;
         case 1:
            _parent._parent.createThing({type:"幻魔晶石"});
            _loc4_ = "获得 幻魔晶石";
            break;
         case 2:
            _parent._parent.createThing({type:"灵魂晶石"});
            _loc4_ = "获得 灵魂晶石";
            break;
         case 3:
            _parent._parent.createThing({type:"灵魂晶石"});
            _parent._parent.createThing({type:"灵魂晶石"});
            _loc4_ = "获得 灵魂晶石×2";
            break;
         case 4:
            _parent._parent.createThing({type:"小元素石"});
            _loc4_ = "获得 小元素石";
            break;
         case 5:
            _parent._parent.createThing({type:"大元素石"});
            _loc4_ = "获得 大元素石";
      }
      switch(target.holes)
      {
         case 1:
            _parent._parent.createThing({type:"初级月光宝盒"});
            _loc4_ += "\r获得 初级月光宝盒";
            break;
         case 2:
            _parent._parent.createThing({type:"初级月光宝盒"});
            _parent._parent.createThing({type:"初级月光宝盒"});
            _parent._parent.createThing({type:"初级月光宝盒"});
            _loc4_ += "\r获得 初级月光宝盒×3";
            break;
         case 3:
            _parent._parent.createThing({type:"中级月光宝盒"});
            _parent._parent.createThing({type:"中级月光宝盒"});
            _loc4_ += "\r获得 中级月光宝盒×2";
      }
      if(target.levels >= 60)
      {
         _parent._parent.createThing({type:"幻魔之心"});
         _loc4_ += "\r获得 幻魔之心";
      }
      _loc5_ = Math.floor(target.mhdj / 6);
      _loc3_ = 0;
      while(_loc3_ < _loc5_ && _loc3_ <= 6)
      {
         _parent._parent.createThing({type:"魔魂之心"});
         _loc3_ = _loc3_ + 1;
      }
      if(_loc5_ > 0)
      {
         _loc4_ += "\r获得 魔魂之心×" + _loc5_;
      }
      switch(target.element)
      {
         case 0:
            break;
         case 1:
            _parent._parent.createThing({type:"风元素"});
            _loc4_ += "\r获得 风元素";
            break;
         case 2:
            _parent._parent.createThing({type:"火元素"});
            _loc4_ += "\r获得 火元素";
            break;
         case 3:
            _parent._parent.createThing({type:"水元素"});
            _loc4_ += "\r获得 水元素";
            break;
         case 4:
            _parent._parent.createThing({type:"地元素"});
            _loc4_ += "\r获得 地风元素";
            break;
         case 5:
            _parent._parent.createThing({type:"雷元素"});
            _loc4_ += "\r获得 雷元素";
      }
      _global.msg.open("\r\r" + _loc4_);
      return true;
   }
   _global.msg.open("\r\r\r这个东西不能分解");
   return false;
}

functions.give:
{
   if("空格" != this.包格1.type && undefined != this.包格1.type && funName != undefined)
   {
      if(this.funName(this.包格1) == true)
      {
         if(this.包格1.number > 0)
         {
            return false;
         }
         this.包格1.setThing({type:"空格"});
         return true;
      }
   }
   return false;
}

functions.setThing:
{
   if(target.number > 0 && this.包格1.type == target.type && this.包格1.name == target.name)
   {
      this.包格1.number += target.number;
      return true;
   }
   if("空格" != this.包格1.type && undefined != this.包格1.type)
   {
      this._parent.backPack.setThing(this.包格1);
   }
   this.包格1.setThing(target);
   return true;
}
